fn is_end(self, version, _rnd, player, data, team_plan, _debug) -> bool

// --- 164: team_plan.take_active(JungleType::Morgard) (인라인) ---
//     take_active(camp) == (self.objective_target() == Some(camp))
//     objective_target() (team_plan.rs:230-231) 은 TeamPlan.objective(+0x41f) 태그를 JungleType 으로 매핑.
//     Morgard 경로만 살아남아 `tag == 0` 비교로 접혔다.
if team_plan.objective.tag != 0 /*Some(MainObjective::Morgard)*/ { return true }

// --- 169 ---
let team = player.info.team;                       // PlayerState+0x930
let camp_pos: (u64,u64) = data.context.map.camp_pos(JungleType::Morgard /*4*/, team == 0);

// --- 172: team_plan.take_setup_like(JungleType::Morgard) (인라인, team_plan.rs:257-258) ---
let setup_like = (team_plan.objective.tag == 0) && (team_plan.objective.Morgard.phase == ObjectPhase::Setup /*1*/);

// --- 173 ---
if setup_like {
    // --- 174 ---
    if team_plan.v24_objective_setup_should_release_to_passive(version, player, data, JungleType::Morgard) {
        return true;                                  // 셋업 단계인데 '패시브로 풀어야 한다'면 종료
    }

    // --- 179 ---
    if data.cache.game.is_visible_cell(team, camp_pos.0 / 32000, camp_pos.1 / 32000) {
        // --- 180~181 ---
        // AbstractGameWithCache.player_champion[1 - team] = 적팀 5칸 [Option<&Entity>;5]
        let nearest_to_camp_enemy = data.cache.player_champion[1 - team].iter()
            .filter_map(|o| o)                                            // iter_champions::{closure#0}
            .filter(|e| data.blackboard[1 - team]                          // is_end::{closure#0}
                          .is_recent_visible(data.cache.game, player, e))
            .min_by_key(|e| {                                             // is_end::{closure#1}
                let dx = abs_diff(e.x /*+0x660*/, camp_pos.0);
                let dy = abs_diff(e.y /*+0x668*/, camp_pos.1);
                dx*dx + dy*dy
            });

        // --- 183 ---
        let Some(nearest_to_camp_enemy) = nearest_to_camp_enemy else { return true };
        //   적 챔피언이 하나도 (최근 목격된 채로) 없으면 종료

        // --- 184 ---
        let dx = abs_diff(nearest_to_camp_enemy.x, camp_pos.0);
        let dy = abs_diff(nearest_to_camp_enemy.y, camp_pos.1);
        if dx*dx + dy*dy > 22500000000 /*150000^2*/ { return true }
        //   가장 가까운 적이 캠프에서 150000 보다 멀면 종료
    }
    // is_visible_cell == false 이면 180~184 를 통째로 건너뛰고 193 으로 간다
}

// --- 193 (setup_like 여부와 무관하게 항상 도달하는 꼬리) ---
let moba: &MobaMode = data.cache.game.get_game_mode().as_moba().unwrap();  // as_moba 가 None 이면 panic
let epic: Option<&Entity> = moba.jungle_runner.epic.live_list.get(0)
        .and_then(|e| data.cache.game.get_entity_by_id(*e));

// --- 194 ---
if epic.is_none() {
    // 에픽 몬스터가 필드에 없다 → 리스폰까지 15초 넘게 남았으면 종료
    return moba.jungle_runner.epic.next_respawn_tick
              .saturating_sub(data.cache.game.tick())
           > data.context.setting.tick_per_second * 15;
}
return false;   // 에픽이 살아 있으면 계속 사냥/포킹

// 정리 — true(종료)가 되는 5가지 경로:
//  (1) 164: team_plan 의 주 오브젝트가 Morgard 가 아님
//  (2) 174: setup 단계에서 v24_objective_setup_should_release_to_passive == true
//  (3) 183: setup 단계 + 캠프 셀이 보이는데 최근목격 적 챔피언이 0명
//  (4) 184: 그 중 가장 가까운 적이 캠프에서 150000 초과로 멀다
//  (5) 194: 에픽이 필드에 없고 리스폰까지 15초 초과로 남음
// false(계속)가 되는 경로는 (5)의 반대와 '에픽이 살아있음' 뿐이다.
